ocodelock.deploybox")); permissionDeployLocker = Convert.ToString(GetConfig("Permissions", "permissionDeployLocker", "autocodelock.deploylocker")); permissionAutoLock = Convert.ToString(GetConfig("Permissions", "permissionAutoLock", "autocodelock.autolock")); permissionNoLockNeed = Convert.ToString(GetConfig("Permissions", "permissionNoLockNeed", "autocodelock.nolockneed")); permissionAll = Convert.ToString(GetConfig("Permissions", "permissionAll", "autocodelock.all")); pluginPrefix = Convert.ToString(GetConfig("Formatting", "pluginPrefix", "Авто закрытие замков")); prefixColor = Convert.ToString(GetConfig("Formatting", "prefixColor", "orange")); prefixFormat = Convert.ToString(GetConfig("Formatting", "prefixFormat", "<color={0}>{1}</color>: ")); colorTextMsg = Convert.ToString(GetConfig("Formatting", "colorTextMsg", "white")); colorCmdUsage = Convert.ToString(GetConfig("Formatting", "colorCmdUsage", "yellow")); colorON = Convert.ToString(GetConfig("Formatting", "colorON", "green")); colorOFF = Convert.ToString(GetConfig("Formatting", "colorOFF", "silver")); AutoLock = Convert.ToBoolean(GetConfig("PlayerDefaults", "AutoLock", true)); DeployDoor = Convert.ToBoolean(GetConfig("PlayerDefaults", "DeployDoor", false)); DeployBox = Convert.ToBoolean(GetConfig("PlayerDefaults", "DeployBox", false)); DeployLocker = Convert.ToBoolean(GetConfig("PlayerDefaults", "DeployLocker", false));  if (!Changed) return; SaveConfig(); Changed = false; }  protected override void LoadDefaultConfig() { Config.Clear(); LoadVariables(); } void LoadDefaultMessages() { lang.RegisterMessages(new Dictionary<string, string> { {"AutoLockEnabled", "Автозакрытие замков включен"}, {"AutoLockDisabled", "Автозакрытие замков выключен"}, {"DeployLockDoorEnabled", "Двери будут включать у себя кодовые замки"}, {"DeployLockDoorDisabled", "Двери не будут включать у себя кодовые замки"}, {"DeployLockBoxEnabled", "Сундуки будут включать у себя кодовые замки"}, {"DeployLockBoxDisabled", "Сундуки не будут включать у себя кодовые замки"}, {"DeployLockLockerEnabled", "Locker будет включать у себя кодовые замки"}, {"DeployLockLockerDisabled", "Locker не будет включать у себя кодовые замки"}, {"CodeAuth", "Замок автоматически закрыт, PIN-код: <color=red>{0}</color>"}, {"NoAccess", "Вам не предоставлена эта функция"}, {"NotSupported", "Конкретная функция '{0}' не доступна"}, {"CommandUsage", "Используйте команду:"}, {"CommandToggle", "Для влючения или отключения используйте (on<>off)"}, {"CommandAutolock", "Автозакрытие:"}, {"CommandPinCode", "Ваш Pin-код:"}, {"CommandPinCodeNotSet", "Случайные 8 цифр"}, {"CommandPinCodeSetTo", "Ваш новый pin-код:"}, {"CommandPinCodeHelp", "Введите PIN-код <color={0}>/{1} pin <1234></color> (4 цифры)"}, {"CommandDeployDoor", "Автозакрытие дверей:"}, {"CommandDeployBox", "Автозакрытие сундуков:"}, {"CommandDeployLocker", "Автоблокировка:"}, },this); }  void Loaded() { LoadVariables(); LoadDefaultMessages(); cmd.AddChatCommand(codelockCommand, this, "CodeLockCommand"); }  void OnServerInitialized() { if (!permission.PermissionExists(permissionDeployDoor)) permission.RegisterPermission(permissionDeployDoor, this); if (!permission.PermissionExists(permissionAutoLock)) permission.RegisterPermission(permissionAutoLock, this); if (!permission.PermissionExists(permissionDeployBox)) permission.RegisterPermission(permissionDeployBox, this); if (!permission.PermissionExists(permissionDeployLocker)) permission.RegisterPermission(permissionDeployLocker, this); if (!permission.PermissionExists(permissionAll)) permission.RegisterPermission(permissionAll, this); if (!permission.PermissionExists(permissionNoLockNeed)) permission.RegisterPermission(permissionNoLockNeed, this); playerPrefs = Interface.GetMod().DataFileSystem.ReadObject<StoredData>(this.Title); foreach(var player in BasePlayer.activePlayerList) SetPlayer(player); foreach(var player in BasePlayer.sleepingPlayerList) SetPlayer(player); Interface.Oxide.DataFileSystem.WriteObject(this.Title, playerPrefs); Initialized = true; }  void SetPlayer(BasePlayer player) { if (player == null) return; PlayerInfo p = null; if (!playerPrefs.PlayerInfo.TryGetValue(player.userID, out p)) { var info = new PlayerInfo(); info.AL = AutoLock; info.DLD = DeployDoor; info.DLB = DeployBox; info.DLL = DeployLocker; info.PC = UnityEngine.Random.Range(1999,9999); playerPrefs.PlayerInfo.Add(player.userID, info); return; } return; }  void OnPlayerInit(BasePlayer player) { SetPlayer(player); }  void Unload() { SaveData(); }  void OnServerSave() { SaveData(); }  void SaveData() { Interface.Oxide.DataFileSystem.WriteObject(this.Title, playerPrefs); }  void OnItemDeployed(Deployer deployer, BaseEntity entity) { if (!Initialized || deployer.GetOwnerPlayer() == null || deployer.GetModDeployable() == null || deployer.GetModDeployable().name ==  "doorcloser.item" || !entity.HasSlot(BaseEntity.Slot.Lock) || !(entity.GetSlot(BaseEntity.Slot.Lock) is CodeLock)) return; var owner = deployer.GetOwnerPlayer(); if ((permission.UserHasPermission(owner.UserIDString, permissionAutoLock) || permission.UserHasPermission(owner.UserIDString, permissionAll)) && playerPrefs.PlayerInfo[owner.userID].AL) { var codelock = entity.GetSlot(BaseEntity.Slot.Lock) as CodeLock; List<ulong> whitelistPlayers = new List<ulong>(); whitelistPlayers.Add(owner.userID); if (playerPrefs.PlayerInfo[owner.userID].PC != 0) _code.SetValue(codelock, Convert.ToString(playerPrefs.PlayerInfo[owner.userID].PC)); else _code.SetValue(codelock, Convert.ToString(UnityEngine.Random.Range(10000000, 90000000))); _hasCode.SetValue(codelock, true); _whitelistPlayers.SetValue(codelock, whitelistPlayers); (codelock as BaseEntity).SetFlag(BaseEntity.Flags.Locked, true, false); Effect.server.Run("assets/prefabs/locks/keypad/effects/lock.code.updated.prefab", entity.transform.position); if (notifyAuthCodeLock) { var code = (string)_code.GetValue(codelock); if (owner.net.connection.info.GetBool("global.streamermode")) code = "****"; PrintToChat(owner, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>"+ lang.GetMessage("CodeAuth", this, owner.UserIDString), code +"</color>"); } } }  void OnEntityBuilt(Planner planner, GameObject obj) { if (!Initialized || planner == null || planner.GetOwnerPlayer() == null || obj.GetComponent<BaseEntity>() == null || obj.GetComponent<BaseEntity>().OwnerID == 0) return; BaseEntity entity = obj.GetComponent<BaseEntity>(); BasePlayer player = planner.GetOwnerPlayer(); if (player == null || !playerPrefs.PlayerInfo.ContainsKey(player.userID)) return; if (entity is Door && (entity as Door).canTakeLock) { if ((permission.UserHasPermission(player.UserIDString, permissionDeployDoor) || permission.UserHasPermission(player.UserIDString, permissionAll)) && playerPrefs.PlayerInfo[player.userID].DLD) { Item codelock = null; bool cap = false; if (permission.UserHasPermission(player.UserIDString, permissionNoLockNeed)) { codelock = ItemManager.CreateByItemID(-975723312); player.inventory.containerMain.capacity += 1; player.inventory.GiveItem(codelock, player.inventory.containerMain); cap = true; } else codelock = player.inventory.FindItemID(-975723312); if(codelock != null) { var deploy = codelock.GetHeldEntity() as Deployer; deploy.DoDeploy_Slot(deploy.GetDeployable(), player.eyes.HeadRay(),entity.net.ID); if (cap) player.inventory.containerMain.capacity -= 1; return; } } } if (entity is BoxStorage && (entity as BaseEntity).HasSlot(BaseEntity.Slot.Lock)) { if ((permission.UserHasPermission(player.UserIDString, permissionDeployBox) || permission.UserHasPermission(player.UserIDString, permissionAll)) && playerPrefs.PlayerInfo[player.userID].DLB) { Item codelock = null; bool cap = false; if (permission.UserHasPermission(player.UserIDString, permissionNoLockNeed)) { codelock = ItemManager.CreateByItemID(-975723312); player.inventory.containerMain.capacity += 1; player.inventory.GiveItem(codelock, player.inventory.containerMain); cap = true; } else codelock = player.inventory.FindItemID(-975723312); if(codelock != null) { var deploy = codelock.GetHeldEntity() as Deployer; deploy.DoDeploy_Slot(deploy.GetDeployable(), player.eyes.HeadRay(),entity.net.ID); } if (cap) player.inventory.containerMain.capacity -= 1; return; } } if (entity is Locker && (entity as BaseEntity).HasSlot(BaseEntity.Slot.Lock)) { if ((permission.UserHasPermission(player.UserIDString, permissionDeployLocker) || permission.UserHasPermission(player.UserIDString, permissionAll)) && playerPrefs.PlayerInfo[player.userID].DLL) { Item codelock = null; bool cap = false; if (permission.UserHasPermission(player.UserIDString, permissionNoLockNeed)) { codelock = ItemManager.CreateByItemID(-975723312); player.inventory.containerMain.capacity += 1; player.inventory.GiveItem(codelock, player.inventory.containerMain); cap = true; } else codelock = player.inventory.FindItemID(-975723312); if(codelock != null) { var deploy = codelock.GetHeldEntity() as Deployer; deploy.DoDeploy_Slot(deploy.GetDeployable(), player.eyes.HeadRay(),entity.net.ID); } if (cap) player.inventory.containerMain.capacity -= 1; return; } } }  void CodeLockCommand(BasePlayer player, string command, string[] args) { if (!permission.UserHasPermission(player.UserIDString, permissionAutoLock) && !permission.UserHasPermission(player.UserIDString, permissionDeployDoor) && !permission.UserHasPermission(player.UserIDString, permissionDeployBox) && !permission.UserHasPermission(player.UserIDString, permissionDeployLocker) && !permission.UserHasPermission(player.UserIDString, permissionAll)) { PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>"+ lang.GetMessage("NoAccess", this, player.UserIDString) +"</color>"); return; } if(args.Length == 0) { var sb = new StringBuilder(); sb.AppendLine($"<size=16><color={prefixColor}>{pluginPrefix}</color></size>"); sb.Append($"<color={colorTextMsg}>"); sb.AppendLine(lang.GetMessage("CommandUsage", this, player.UserIDString)+$"<color={colorCmdUsage}>/{codelockCommand} <опция></color>\n"+lang.GetMessage("CommandToggle", this, player.UserIDString)); if (permission.UserHasPermission(player.UserIDString, permissionAutoLock) || permission.UserHasPermission(player.UserIDString, permissionAll)) sb.AppendLine($"<color={colorCmdUsage}>auto</color> - " +lang.GetMessage("CommandAutolock", this, player.UserIDString)+" "+(playerPrefs.PlayerInfo[player.userID].AL ? $"<color={colorON}>ВКЛ</color>" : $"<color={colorOFF}>ВЫКЛ</color>")); var pin = Convert.ToString(playerPrefs.PlayerInfo[player.userID].PC); if (player.net.connection.info.GetBool("global.streamermode")) pin = "****"; sb.AppendLine($"<color={colorCmdUsage}>pin</color> - " +lang.GetMessage("CommandPinCode", this, player.UserIDString)+" "+(playerPrefs.PlayerInfo[player.userID].PC > 0 ? $"<color={colorCmdUsage}>{pin}</color>" : $"<color={colorOFF}>{lang.GetMessage("CommandPinCodeNotSet", this, player.UserIDString)}</color>") ); if (permission.UserHasPermission(player.UserIDString, permissionDeployDoor) || permission.UserHasPermission(player.UserIDString, permissionAll)) sb.AppendLine($"<color={colorCmdUsage}>door</color> - " +lang.GetMessage("CommandDeployDoor", this, player.UserIDString)+" "+(playerPrefs.PlayerInfo[player.userID].DLD ? $"<color={colorON}>ВКЛ</color>" : $"<color={colorOFF}>ВЫКЛ</color>")); if (permission.UserHasPermission(player.UserIDString, permissionDeployBox) || permission.UserHasPermission(player.UserIDString, permissionAll)) sb.AppendLine($"<color={colorCmdUsage}>box</color> - " +lang.GetMessage("CommandDeployBox", this, player.UserIDString)+" "+(playerPrefs.PlayerInfo[player.userID].DLB ? $"<color={colorON}>ВКЛ</color>" : $"<color={colorOFF}>ВЫКЛ</color>")); if (permission.UserHasPermission(player.UserIDString, permissionDeployLocker) || permission.UserHasPermission(player.UserIDString, permissionAll)) sb.AppendLine($"<color={colorCmdUsage}>locker</color> - " +lang.GetMessage("CommandDeployLocker", this, player.UserIDString)+" "+(playerPrefs.PlayerInfo[player.userID].DLL ? $"<color={colorON}>ВКЛ</color>" : $"<color={colorOFF}>ВЫКЛ</color>")); sb.Append("</color>"); SendReply(player, sb.ToString().TrimEnd()); return; } switch (args[0].ToLower()) { case "auto": if (permission.UserHasPermission(player.UserIDString, permissionAutoLock) || permission.UserHasPermission(player.UserIDString, permissionAll)) { playerPrefs.PlayerInfo[player.userID].AL = !playerPrefs.PlayerInfo[player.userID].AL; PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + (playerPrefs.PlayerInfo[player.userID].AL ? lang.GetMessage("AutoLockEnabled", this, player.UserIDString) : lang.GetMessage("AutoLockDisabled", this, player.UserIDString)) +"</color>"); } else goto case "noaccess"; break; case "door": if (permission.UserHasPermission(player.UserIDString, permissionDeployDoor) || permission.UserHasPermission(player.UserIDString, permissionAll)) { playerPrefs.PlayerInfo[player.userID].DLD = !playerPrefs.PlayerInfo[player.userID].DLD; PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + (playerPrefs.PlayerInfo[player.userID].DLD ? lang.GetMessage("DeployLockDoorEnabled", this, player.UserIDString) : lang.GetMessage("DeployLockDoorDisabled", this, player.UserIDString)) +"</color>"); } else goto case "noaccess"; break; case "box": if (permission.UserHasPermission(player.UserIDString, permissionDeployBox) || permission.UserHasPermission(player.UserIDString, permissionAll)) { playerPrefs.PlayerInfo[player.userID].DLB = !playerPrefs.PlayerInfo[player.userID].DLB; PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + (playerPrefs.PlayerInfo[player.userID].DLB ? lang.GetMessage("DeployLockBoxEnabled", this, player.UserIDString) : lang.GetMessage("DeployLockBoxDisabled", this, player.UserIDString)) +"</color>"); } else goto case "noaccess"; break; case "locker": if (permission.UserHasPermission(player.UserIDString, permissionDeployLocker) || permission.UserHasPermission(player.UserIDString, permissionAll)) { playerPrefs.PlayerInfo[player.userID].DLL = !playerPrefs.PlayerInfo[player.userID].DLL; PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + (playerPrefs.PlayerInfo[player.userID].DLL ? lang.GetMessage("DeployLockLockerEnabled", this, player.UserIDString) : lang.GetMessage("DeployLockLockerDisabled", this, player.UserIDString)) +"</color>"); } else goto case "noaccess"; break; case "pin": if (permission.UserHasPermission(player.UserIDString, permissionAutoLock) || permission.UserHasPermission(player.UserIDString, permissionAll)) { int pin; if (args.Length != 2 || int.TryParse(args[1], out pin) == false || args[1].Length != 4 || pin.ToString().Length < 4) { PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + string.Format(lang.GetMessage("CommandPinCodeHelp", this, player.UserIDString), colorCmdUsage, codelockCommand)); return; }  playerPrefs.PlayerInfo[player.userID].PC = pin; PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + string.Format(lang.GetMessage("CommandPinCodeSetTo", this, player.UserIDString)) + $" <color={colorCmdUsage}>{pin}</color></color>"); } else goto case "noaccess"; break; case "noaccess": PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>"+ lang.GetMessage("NoAccess", this, player.UserIDString) +"</color>"); break; default: PrintToChat(player, string.Format(prefixFormat,prefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + string.Format(lang.GetMessage("NotSupported", this, player.UserIDString), args[0]) + "</color>"); break; } } } }